<?php
/**
 * قوانین مشترک نگارش و سئو برای تمام انواع محتوا (تولید تکی و تولید انبوه)
 *
 * @package WP_Internal_Link_Analyzer
 */

namespace Khazan\Services\Content;

use Khazan\Core\Settings;

if (!defined('ABSPATH')) {
    exit;
}

final class ContentRules {

    /**
     * قوانین قالب HTML، توزیع کلیدواژه و نگارش فعال؛ برای محصول، دسته‌بندی و مقاله یکسان است
     */
    /**
     * قانون سخت‌گیرانه تکرار دقیق کلیدواژه کانونی مقاله (Exact Match): ۴ تا ۶ بار بسته به طول متن
     */
    public static function article_keyword_rule($word_count = 0) {
        $words = max(0, (int) $word_count);
        $min = max(1, (int) ceil($words * SeoStandards::get('density_min') / 100));
        $max = max($min, (int) floor($words * SeoStandards::get('density_max') / 100));
        return "کلیدواژه کانونی را عیناً و دقیقاً با همان شکل و ترتیب کلمات (Exact Match، نه فقط بخشی از آن) حداقل {$min} بار و حداکثر {$max} بار (چگالی " . SeoStandards::get('density_min') . " تا " . SeoStandards::get('density_max') . " درصد) به‌صورت طبیعی در متن بیاور. حضور دقیق آن در این جاها الزامی است: ۱۰۰ واژه نخست، حداقل یک زیرعنوان H2 (و حداکثر " . SeoStandards::get('h2_keyword_max') . " زیرعنوان H2)، میانه محتوا و پاراگراف نتیجه‌گیری. بقیه موارد را با مترادف‌ها بیاور. ";
    }

    public static function writing_rules($kind, $word_count = 0) {
        $tags = $kind === Settings::KIND_PRODUCT
            ? 'فقط از <h2>، <h3>، <p>، <ul>، <li>، <strong>، <a> و برای جدول مشخصات از <table>، <thead>، <tbody>، <tr>، <th>، <td> استفاده کن. جدول فقط یک‌بار، فقط با ردیف‌های دارای مقدار واقعی ساخته می‌شود (ردیف «اعلام نشده» ممنوع)، فقط متن ساده دارد و لینک در آن نیست.'
            : 'از <h2>، <h3>، <p>، <ul>، <li>، <strong> و <a> استفاده کن.';
        $density = $kind === Settings::KIND_ARTICLE
            ? self::article_keyword_rule($word_count)
            : "چگالی کلیدواژه کانونی بین " . SeoStandards::get('density_min') . " تا " . SeoStandards::get('density_max') . " درصد کل واژه‌ها باشد (بیشتر از سقف نه)؛ بقیه موارد را با مترادف‌ها بیاور. ";
        return "[قوانین قالب و نگارش]\n" .
            "۱. HTML فشرده بنویس: هر تگ روی همان خط، بدون خط خالی یا فاصله بین تگ‌های بلاک. " . $tags . "\n" .
            "۲. پرسش‌های متداول را با ساختار <h3>سوال</h3><p>پاسخ</p> بنویس.\n" .
            "۳. " . $density . "توزیع باید کاملاً متوازن باشد (Yoast متن را به بخش‌های مساوی تقسیم می‌کند و بخش بدون کلیدواژه یا مترادف خطا می‌گیرد): ۱ بار کلیدواژه کانونی در پاراگراف اول، ۱ بار یکی از مترادف‌ها در اواسط متن (بخش بررسی متریال/رویه)، ۱ بار کلیدواژه کانونی یا مترادف در بخش مزایا/ویژگی‌ها، و ۱ بار در سوالات متداول یا پاراگراف پایانی. از تجمع کلیدواژه‌ها در یک بخش و خالی ماندن بخش‌های دیگر اکیداً خودداری کن؛ هیچ بخش بلندی نباید بدون کلیدواژه یا مترادف بماند.\n" .
            "۴. فاصله بین دو زیرسرفصل (H2/H3) نباید بیشتر از ۲۲۰ واژه باشد.\n" .
            self::external_link_rule() .
            "۶. قانون زیرعنوان‌ها: کلیدواژه کانونی را در حداقل یک زیرعنوان و در حداکثر " . SeoStandards::get('h2_keyword_max') . " زیرعنوان H2 بیاور؛ بقیه زیرعنوان‌ها بدون کلیدواژه کانونی و با مترادف یا موضوع خود بخش نوشته شوند. حداقل " . SeoStandards::get('h2_min') . " زیرعنوان H2 داشته باش.\n" .
            "۷. نگارش فعال: اکیداً از جملات مجهول فارسی (ساخته شده است، تولید می‌شود، طراحی گردیده است، استفاده شده است، به کار رفته است) پرهیز کن و حداکثر ۵٪ جمله‌ها مجهول باشند. جمله‌ها را معلوم بنویس. مثال غلط: «رویه از چرم ساخته شده است». مثال درست: «رویه این مدل از چرم است و ظاهر مرتبی دارد». ادعاهایی مثل نوع چرم، دست‌دوز یا تبریز را فقط وقتی بنویس که در داده‌های ورودی باشد.\n" .
            "۸. کلیدواژه کانونی (focus_keyword) دقیقاً ۲ تا ۴ کلمه است، فرمول [نوع کالا] + [جنسیت] + [نام اختصاصی مدل] (مثل «کفش مردانه ونس فلوتر»)؛ کلمات طبیعی، تبریز، مدل، طرح، اصل، دست‌دوز، کد، فروش، خرید و قیمت هرگز در آن نیایند و جنسیت (مردانه/زنانه) هرگز حذف نشود؛ فقط اگر نام مدل ۱ کلمه‌ای است و ظرفیت ۴ کلمه خالی می‌ماند، درست بعد از نوع کالا اول صفت کاربری (طبی، مجلسی، اسپرت، اداری، راحتی، کلاسیک) و در نبود آن «چرم/چرمی» می‌آید (مثل «کفش طبی مردانه مارکو» یا «بوت چرم زنانه آلفردو») و هرگز کل نام محصول نیست. تمام لینک‌های داخلی، چه به صفحه دیگر و چه از صفحه دیگر، با انکرتکست کوتاه و هدفمند حداکثر ۴ کلمه‌ای ساخته شوند؛ انکر هرگز نام کامل محصول یا یک جمله نباشد. قانون عدم خودرقابتی: انکرتکست هیچ لینک خروجی (دسته‌بندی یا محصول دیگر) نباید با کلیدواژه کانونی همین صفحه یا مترادف‌های اصلی آن برابر باشد یا آن را شامل شود؛ انکر لینک دسته هرگز فقط نام خام دسته (مثل «بوت چرم زنانه») نیست؛ همیشه یکی از پیشوندهای «انواع»، «مجموعه مدل‌های» یا «کلکسیون» به‌همراه نام واقعی دسته است (مثل «انواع بوت چرم زنانه»، ۴ تا ۵ کلمه) و دقیقاً همان عبارت داده‌شده در internal_links را بنویس و انکر لینک هر محصول نام/مدل اختصاصی همان محصول مقصد (مثل «بوت مدل برشکا») باشد.\n" .
            "۹. لحن و دستور نگارش (جملات معلوم و فاعل‌محور): بیش از ۹۵٪ جمله‌های متن باید معلوم، با فاعل مشخص و فعل پویا و مستقیم باشند؛ سهم جمله‌های مجهول باید زیر ۸٪ بماند (سقف استاندارد ۱۰٪ هرگز نقض نشود). الگوهای مجهول پرکاربرد («استفاده شده است»، «عرضه شده است»، «دیده می‌شود»، «ساخته شده است»، «طراحی گردیده است» و مشابه آن‌ها) در کل متن حداکثر ۱ بار مجاز است. مثال‌ها: به‌جای «در رویه این کفش از چرم استفاده شده است» بنویس «رویه کفش از چرم طبیعی تشکیل شده و مقاومت بالایی ارائه می‌دهد»؛ به‌جای «این مدل در تبریز عرضه شده است» بنویس «صنعتگران تبریز این مدل را طراحی و تولید کرده‌اند»؛ به‌جای «در بخش زیره متریال پلی‌اورتان دیده می‌شود» بنویس «طراحان در بخش زیره از پلی‌اورتان بهره برده‌اند». جمله‌ها را کوتاه، روان و ترغیب‌کننده برای خریدار بنویس.\n" .
            "۱۰. ساختار پاراگراف: هر پاراگراف الزاماً داخل تگ صریح <p>...</p> باشد (متن آزاد یا جداسازی فقط با خط خالی ممنوع است) و طول هر <p> حداکثر ۶۰ تا ۹۰ کلمه (۳ تا ۴ جمله کوتاه) باشد؛ پاراگراف بلندتر را به چند <p> بشکن. هرگز بیش از ۱۱۰ کلمه بین دو تگ متوالی ننویس.\n" .
            ($kind === Settings::KIND_PRODUCT ? self::product_link_rules() : '');
    }

    /**
     * سقف و یکتایی لینک‌ها در متن محصول: تعداد طبق استانداردها (۱ دسته‌بندی + محصولات هم‌دسته و هم‌جنسیت) + لینک خارجی تأییدشده اختیاری، هر URL فقط یک‌بار
     */
    public static function product_link_rules() {
        return "۱۱. قانون لینک‌ها در متن محصول: فقط لینک‌هایی را بگذار که در فهرست لینک‌های اجباری داده شده‌اند (دسته‌بندی اصلی و محصولات مرتبط) و لینک خارجی فقط از منابع تأییدشده (در صورت وجود). هر URL فقط یک‌بار در کل محتوا و هر پاراگراف حداکثر ۲ لینک. اگر نام محصول یا دسته در بخش‌های بعدی (مزایا، مشخصات، پرسش‌های متداول) دوباره آمد، لینک نشود و فقط متن ساده باشد.\n";
    }

    /**
     * External links: only from sources the owner verified (BusinessFacts); with none configured the text carries none.
     */
    public static function external_link_rule() {
        $sources = BusinessFacts::verified_sources();
        if (!$sources) {
            return "۵. لینک خارجی نساز؛ هیچ منبع تأییدشده‌ای ثبت نشده و لینک حدسی یا ساختگی ممنوع است.\n";
        }
        list(, $max) = SeoStandards::external_range();
        $lines = array();
        foreach ($sources as $src) $lines[] = $src['url'] . ($src['title'] !== '' ? ' (' . $src['title'] . ')' : '');
        return "۵. حداکثر " . $max . " لینک خارجی و فقط از این منابع تأییدشده، با <a href=\"URL\" target=\"_blank\" rel=\"noopener\"> و انکر توصیفی مرتبط با جمله (نه «اینجا» یا «کلیک کنید»):\n" . implode("\n", $lines) . "\n";
    }

    /**
     * Rules for the secondary keywords (Yoast «مترادف» / «عبارات کلیدی مرتبط» / Rank Math extra keywords).
     */
    public static function synonym_rules() {
        return "[قواعد کلیدواژه‌های فرعی و مترادف (keyword_synonyms)]\n" .
            "۳ تا ۶ عبارت واقعی که کاربر ایرانی برای همین محصول جست‌وجو می‌کند، با ویرگول جدا شده و هر کدام ۲ تا ۴ کلمه؛ مثلاً نوع دیگر نام‌گذاری همان کالا، ترکیب با جنس یا کاربرد («بوت چرم زنانه»، «نیم‌بوت چرمی بانوان»). " .
            "هیچ عبارتی عین کلیدواژه کانونی یا شامل کامل آن نباشد؛ تکراری نباشد؛ نام برند، شهر، قیمت، عدد و کلمات تبلیغاتی (ارزان، تخفیف، ویژه) نیاید؛ عبارت بی‌ربط یا حدسی ننویس. " .
            "هر عبارت را باید بتوان طبیعی و بدون دستکاری دستور زبان در همین متن به کار برد؛ مترادف‌ها را در متن پخش کن (طبق قانون توزیع).\n";
    }

    /**
     * قواعد مشترک عنوان سئو: کلیدواژه در ابتدا، یک ایموجی مرتبط، طول مناسب و بدون نام سایت
     */
    public static function seo_title_rules($kind, $focus = '') {
        if ($kind === Settings::KIND_PRODUCT) return self::product_seo_title_rules($focus);
        $modifiers = array(
            Settings::KIND_ARTICLE  => 'یک مزیت یا نوع محتوا مانند «راهنمای کامل»، «آموزش گام‌به‌گام» یا «روش‌ها»',
            Settings::KIND_CATEGORY => 'یک کلمه تجاری مانند «خرید»، «قیمت» یا «انواع» همراه گستره محصولات همان دسته',
        );
        return "[قواعد عنوان سئو]\n" .
            "۱. طول عنوان (با فاصله‌ها) ۵۰ تا ۶۰ کاراکتر باشد و از ۶۰ بیشتر نشود تا در نتایج گوگل بریده نشود.\n" .
            "۲. عبارت کانونی دقیقاً و بدون هیچ تغییری (عین رشته focus_keyword) در ابتدای عنوان بیاید؛ سپس " . $modifiers[$kind] . " اضافه شود. عنوان باید با محتوای واقعی صفحه و نیت جستجو سازگار باشد و وعده‌ای (تخفیف، ارسال رایگان، رتبه یک و ...) که تایید نشده نباشد.\n" .
            "۳. ایموجی در عنوان ممنوع است. قالب: [عبارت کانونی]؛ [قلاب/ارزش افزوده] | [نام برند]. عبارت «ارسال رایگان» در عنوان نیاید.\n" .
            "۴. نام کوتاه برند را فقط به‌عنوان آخرین بخش بعد از « | » بیاور و فقط اگر در ۶۰ کاراکتر جا شود؛ تکرار کلیدواژه، کلمات پرکننده، حروف درشت لاتین و تیتر کلیک‌طعمه ممنوع است.\n" .
            "۵. توضیحات متا ۱۴۰ تا ۱۵۵ کاراکتر، شامل عبارت کانونی یک‌بار، مزیت اصلی و یک دعوت به اقدام طبیعی باشد.\n";
    }

    /**
     * فرمول عنوان سئوی محصول: [نوع کالا + جنس + جنسیت + مدل] | [مزیت/اصالت + ایموجی] | [برند]
     */
    public static function product_seo_title_rules($focus = '') {
        $brand = Settings::brand_name();
        $brand_label = $brand !== '' ? $brand : 'نام برند';
        $focus = trim((string) $focus);
        return "[قواعد عنوان سئوی محصول]\n" .
            "۱. focus_keyword دقیقاً بین ۲ تا ۴ کلمه است و حتماً هم دسته‌بندی/نوع کالا و هم نام مدل محصول را دارد (مثل «نیم‌بوت چرم زنانه آلفردو» یا «کفش مردانه ونس فلوتر»)؛ فرمول: [نوع کالا] + [جنسیت] + [نام اختصاصی مدل]. کلمات طبیعی، تبریز، مدل، طرح، اصل، دست‌دوز، کد، فروش، خرید و قیمت هرگز در آن نیایند و جنسیت هرگز حذف نشود؛ فقط وقتی نام مدل ۱ کلمه‌ای است و جا برای ۴ کلمه هست، درست بعد از نوع کالا اول صفت کاربری (طبی، مجلسی، اسپرت، اداری، راحتی، کلاسیک) و در نبود آن «چرم/چرمی» می‌آید (مثل «کفش طبی مردانه مارکو» یا «بوت چرم زنانه آلفردو»؛ برای مدل ۲ کلمه‌ای «کفش مردانه ونس فلوتر» بدون صفت اضافه). هرگز کل نام محصول یا عبارت ناقص بدون مدل نیست." . ($focus !== '' ? " برای این محصول: «" . $focus . "»." : '') . "\n" .
            "۲. seo_title با فرمول [دقیقاً همان focus_keyword]؛ [مزیت واقعی و تأییدشده] | [" . $brand_label . "] ساخته می‌شود و با « | نام برند» تمام می‌شود.\n" .
            "۳. بخش اول فقط و دقیقاً focus_keyword است؛ هیچ کلمه اضافه (روزمره، طرح جدید، اصل، تضمینی) یا حذف نام مدل در آن مجاز نیست.\n" .
            "۴. بخش دوم فقط یک مزیت واقعی و تأییدشده است (مثل «اقساط ۴ مرحله‌ای»)؛ ایموجی، «ارسال رایگان» و ادعای تأییدنشده ممنوع است.\n" .
            "۵. بخش سوم صرفاً نام کوتاه برند «" . $brand_label . "» است؛ هیچ توضیح اضافه، شعار سایت (مثل «فروشگاه محصولات چرم ...») یا کلمه عمومی به آن اضافه نکن و جای بخش‌ها را عوض نکن.\n" .
            "۶. طول کل عنوان (با فاصله‌ها) ۵۰ تا ۶۰ کاراکتر و هرگز بیشتر از ۶۰ کاراکتر نباشد تا در نتایج گوگل (SERP) بریده نشود؛ برای کوتاه‌کردن بخش مزیت را خلاصه کن، نه کلیدواژه را.\n" .
            "۷. توضیحات متا ۱۴۰ تا ۱۵۵ کاراکتر، شامل عبارت کانونی یک‌بار، مزیت اصلی و یک دعوت به اقدام طبیعی باشد.\n";
    }

    /**
     * الگوی ثابت ساختار محصول؛ در تولید تکی و انبوه یکسان است و متن هر محصول باید مختص خودش باشد
     */
    public static function product_blueprint() {
        return "[ساختار ثابت محصول - هدف: متن فروش‌محور و قانع‌کننده برای خریدار؛ جمله‌ها و قلاب‌ها را برای هر محصول متفاوت بنویس]\n" .
            "۱. مقدمه (۲ تا ۳ جمله): خریدار را در یک موقعیت واقعی ببین (کجا و با چه لباسی این محصول را می‌پوشد) و بزرگ‌ترین دلیل انتخابش را همان‌جا بگو. کلیدواژه کانونی طبیعی در همین پاراگراف بیاید. شروع با تعارف و جمله‌ی کلی («اگر به دنبال … هستید») ممنوع است.\n" .
            "۲. H2 درباره‌ی جنس و ساخت (۲ پاراگراف کوتاه): فقط ویژگی‌های تأییدشده را بنویس و هر کدام را به فایده‌ی ملموس تبدیل کن (جنس رویه → ظاهر و عمر استفاده؛ زیره → راحتی راه رفتن؛ آستر → حس داخل کفش). عنوان این H2 توصیفی و جذاب باشد، نه فقط «بررسی تخصصی». سپس یک جدول مشخصات: <table><thead><tr><th>ویژگی</th><th>مشخصات</th></tr></thead><tbody>…</tbody></table> فقط با ردیف‌هایی که مقدار واقعی دارند (نوع محصول، جنس رویه، زیره، آستر، نوع دوخت و ...). ردیف بدون مقدار یا با «اعلام نشده/نامشخص» هرگز ننویس؛ اگر کمتر از ۲ ردیف با مقدار واقعی داری، اصلاً جدول نساز.\n" .
            "۳. H2 «مزایا و ارزش خرید»: فهرست <ul><li> با ۴ تا ۶ مورد؛ هر مورد «ویژگی → نتیجه برای خریدار» (مثلاً قابلیت ست‌شدن با چه لباسی، راحتی در چه شرایطی). یک مورد برای اعتماد خرید (ارسال، اقساط، ضمانت بازگشت) فقط از واقعیت‌های تأییدشده‌ی فروشگاه که در داده‌ها آمده، نه بیشتر.\n" .
            "۴. H2 «موقعیت‌های استفاده و ست‌کردن»: ۲ پاراگراف کوتاه و کاربردی درباره‌ی اینکه این محصول با چه لباس‌ها و در چه موقعیت‌هایی بهتر دیده می‌شود. این بخش توصیه‌ی استایل است و ادعای فنی یا آماری نیست.\n" .
            "۵. H2 «سوالات متداول»: ۳ پرسش واقعی خریدار (جنس و نگهداری، ست‌کردن، شرایط خرید) با ساختار <h3>سوال</h3><p>پاسخ کوتاه و مشخص</p>. پرسشی که پاسخ تأییدشده‌ای برایش نداری ننویس.\n" .
            "۶. پاراگراف پایانی (۲ جمله): خریدار را مشخصاً به انتخاب و خرید همین مدل دعوت کن و یک دلیل قوی برای تصمیم بده.\n" .
            "لحن: مثل یک فروشنده‌ی ایرانی خوش‌صحبت بنویس؛ مقدارهای مشخصات (مثل «چرم تبریز - چرم گاوی») را عین داده کپی نکن و هر بار با جمله‌ی تازه و روان بازگو کن؛ از قالب‌های تکراری و جمله‌های کلیشه‌ای پرهیز کن.\n            قالب بسته: فقط همین H2های بالا (جنس و ساخت، مزایا، موقعیت‌های استفاده، سوالات متداول) مجازند؛ H2 تازه‌ای مثل «شرایط خرید» یا «چرا این مدل» اضافه نکن. نکات اعتماد فروشگاه (ارسال، اقساط، ضمانت بازگشت) در کل متن فقط یک‌بار بیایند، همان یک مورد در فهرست مزایا؛ در سوالات متداول و جمع‌بندی تکرارشان نکن. سوالات متداول هرگز درباره‌ی ارسال، اقساط، پرداخت یا بازگشت کالا نباشند (فقط نگهداری، ست‌کردن، سایز و راحتی). هیچ دو لینکی در یک جمله یا یک پاراگراف نیایند؛ هر لینک در پاراگراف جدا و با دست‌کم یک پاراگراف فاصله. لینک به محصول از نوع دیگر (مثلاً کفش روزمره در صفحه‌ی بوت) فقط اگر در لیست لینک‌ها آمده باشد و با جمله‌ی مرتبط. ردیف‌های جدول را از هم جدا نگه دار: هر ردیف یک ویژگی (آستر و کفی دو ردیف جدا یا فقط ردیفی که در داده‌ها هست) و مقدار را کوتاه و طبیعی بنویس، بدون «منشأ»، «با پایه» و ترکیب‌های ماشینی. هر عبارت وصفی (مثل «ظاهر مرتب/منظم/تمیز»، «چرم طبیعی»، «حس راحت») در کل متن حداکثر دو بار بیاید؛ مترادف طبیعی بساز. رنگ، بافت، فرم پا و نوع شلوار یا لباس را فقط اگر در داده‌ها آمده بنویس. پاراگراف پایانی فقط دعوت به خرید است و هیچ لینکی ندارد. ادعای قیمتی («به‌صرفه»، «ارزان»)، «از مد نمی‌افتد»، «مناسب همه‌ی فصل‌ها» و هر ادعای بی‌منبع ممنوع است. جمله‌ی مجهول (ساخته شده، قرار گرفته، معرفی می‌شود) ننویس؛ فاعل‌دار بنویس. هر ست‌کردن یا موقعیت استفاده را فقط یک‌بار در کل متن بگو؛ تکرار همان نکته با کلمات دیگر ممنوع است.
ممنوع در همه‌ی بخش‌ها: عبارت‌های «اعلام نشده»، «ثبت نشده»، «مشخص نیست»، «نمی‌توان گفت»، «به مشخصات رسمی تکیه کنید»، «بدون اتکا به حدس»، «اطلاعات تأییدشده»؛ حرف‌زدن درباره‌ی خود متن، خود صفحه یا اینکه فروشگاه محصولات این دسته را چگونه معرفی می‌کند؛ تکرار یک جمله یا یک نکته با کلمات دیگر؛ تعارف و پرکردن برای رسیدن به تعداد کلمه. اگر مطلب مفید کم است، کوتاه‌تر بنویس ولی مفید بماند. H1 و بخش اضافه نساز، عنوان هدینگ‌ها را طبیعی بنویس و طبق قانون ۶ کلیدواژه کانونی را در حداکثر ۲ زیرعنوان H2 بیاور.\n";
    }

    /**
     * عبارت کلیدی کوتاه از نام محصول: حذف «مدل ...» و کدهای انتهایی، و نگه‌داشتن حداکثر ۴ کلمه
     */
    public static function short_keyword($title) {
        $title = trim(preg_replace('/\s+/u', ' ', (string) $title));
        if ($title === '') return '';
        $base = trim(preg_split('/(?:^|\s+)مدل(?:\s|$)/u', $title)[0]);
        $words = array_values(array_filter(explode(' ', $base), 'strlen'));
        // کدهای مدل مانند «V2» یا «۱۲۳-AB» در انتها معمولاً مفهوم جستجو ندارند.
        while ($words && preg_match('/[0-9A-Za-z\x{0660}-\x{0669}\x{06F0}-\x{06F9}]/u', end($words))) array_pop($words);
        if (!$words) return $title;
        return implode(' ', array_slice($words, 0, 4));
    }
}
